import sys, json
raw = sys.stdin.read()
start = raw.index('{')
end = raw.rindex('}') + 1
data = json.loads(raw[start:end])
with open('after-cpm-packages.json', 'w') as f:
    json.dump(data, f, indent=2)

# Compare with baseline
with open('baseline-packages.json') as f:
    baseline = json.load(f)

changes = []
unchanged = []
for bp in baseline['projects']:
    proj = bp['path'].split('/')[-1]
    for fw in bp['frameworks']:
        for pkg in fw['topLevelPackages']:
            pid = pkg['id']
            old_ver = pkg['resolvedVersion']
            # find in after
            new_ver = None
            for ap in data['projects']:
                if ap['path'].split('/')[-1] == proj:
                    for afw in ap['frameworks']:
                        for apkg in afw['topLevelPackages']:
                            if apkg['id'] == pid:
                                new_ver = apkg['resolvedVersion']
            if new_ver and new_ver != old_ver:
                changes.append((proj, pid, old_ver, new_ver))
            else:
                unchanged.append((proj, pid, old_ver))

print('=== CHANGES ===')
for c in changes:
    print(f'{c[0]:20s} {c[1]:40s} {c[2]:10s} -> {c[3]}')
print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'{u[0]:20s} {u[1]:40s} {u[2]}')
"

